if(proof.nativeSources){const p=proof.nativeSources,headers={'oai-authenticated-user-id':proof.owner,'oai-authenticated-user-email':proof.owner+'@example.test',Origin:'http://127.0.0.1:8799','Content-Type':'application/json'},pending=p.pending,r=await fetch('http://127.0.0.1:8799/api/native-sources',{method:'POST',headers,body:JSON.stringify({action:'preview',id:pending.id,expectedConfigurationRevision:pending.review.source.configurationRevision,accountTargets:pending.review.source.accountTargets})});assert.equal(r.status,200);assert.deepEqual(await r.json(),pending.review);const complete=await fetch('http://127.0.0.1:8799/api/native-sources?id='+p.complete.id,{headers});assert.equal(complete.status,200);assert.deepEqual(await complete.json(),p.complete.result);for(const item of [p.pending,p.complete]){const original=await fetch('http://127.0.0.1:8799/api/native-sources?id='+item.id+'&format=original',{headers});assert.equal(original.status,200);assert.equal(Buffer.from(await original.arrayBuffer()).toString('hex'),item.originalHex);}const deleted=await fetch('http://127.0.0.1:8799/api/native-merge?requestId='+p.deletedRequest,{headers});assert.equal(deleted.status,200);assert.equal((await deleted.json()).complete,true);}
if(proof.largeNativeSource){const p=proof.largeNativeSource,headers={'oai-authenticated-user-id':p.owner,'oai-authenticated-user-email':p.owner+'@example.test'},r=await fetch('http://127.0.0.1:8799/api/native-sources?id='+p.id,{headers});assert.equal(r.status,200);assert.deepEqual(await r.json(),p.result);const original=await fetch('http://127.0.0.1:8799/api/native-sources?id='+p.id+'&format=original',{headers});assert.equal(original.status,200);const {createHash}=await import('node:crypto');assert.equal(createHash('sha256').update(Buffer.from(await original.arrayBuffer())).digest('hex'),p.sha256);}

